CREATE TABLE platform_user (id UUID PRIMARY KEY, username VARCHAR(120) NOT NULL UNIQUE, role_code VARCHAR(40) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE api_client (id UUID PRIMARY KEY, client_name VARCHAR(120) NOT NULL UNIQUE, token_hash VARCHAR(255) NOT NULL, role_code VARCHAR(40) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE data_source (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, jdbc_url VARCHAR(500) NOT NULL, database_name VARCHAR(128) NOT NULL, username VARCHAR(120) NOT NULL, secret_reference VARCHAR(255) NOT NULL, status VARCHAR(24) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE dataset (id UUID PRIMARY KEY, data_source_id UUID NOT NULL REFERENCES data_source(id), name VARCHAR(120) NOT NULL, schema_name VARCHAR(128) NOT NULL, object_name VARCHAR(128) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(data_source_id, name));
CREATE TABLE dataset_field (id UUID PRIMARY KEY, dataset_id UUID NOT NULL REFERENCES dataset(id) ON DELETE CASCADE, physical_name VARCHAR(128) NOT NULL, display_name VARCHAR(120) NOT NULL, starrocks_type VARCHAR(80) NOT NULL, dimension_enabled BOOLEAN NOT NULL, metric_enabled BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(dataset_id, physical_name));
CREATE TABLE dimension (id UUID PRIMARY KEY, dataset_id UUID NOT NULL REFERENCES dataset(id) ON DELETE CASCADE, dataset_field_id UUID NOT NULL REFERENCES dataset_field(id), name VARCHAR(120) NOT NULL, display_name VARCHAR(120) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(dataset_id, name), UNIQUE(dataset_id, dataset_field_id));
CREATE TABLE metric (id UUID PRIMARY KEY, dataset_id UUID NOT NULL REFERENCES dataset(id) ON DELETE CASCADE, dataset_field_id UUID REFERENCES dataset_field(id), name VARCHAR(120) NOT NULL, display_name VARCHAR(120) NOT NULL, aggregation VARCHAR(32) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(dataset_id, name));
CREATE TABLE audit_event (id UUID PRIMARY KEY, actor_id VARCHAR(120) NOT NULL, action VARCHAR(80) NOT NULL, resource_type VARCHAR(80) NOT NULL, resource_id UUID NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
